import React from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import HeroImage from "assets/img/bg1.png"; // ← adapte si besoin: "../assets/img/bg1.png"

export default function Index() {
  return (
    <>
      {/* Navbar fixée en haut */}
      <IndexNavbar fixed />

      {/* HERO : démarre sous la navbar (64px mobile ~ h-16, 80px desktop ~ h-20) */}
      <section className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center">
        {/* Calque 1 : image de fond */}
        <div
          className="absolute inset-0 bg-cover bg-center"
          style={{ backgroundImage: `url(${HeroImage})` }}
        />

        {/* Calque 2 : filtre marron (#6B140F) avec opacité */}
        <div
          className="absolute inset-0"
          style={{ backgroundColor: "rgba(107, 20, 15, 0.6)" }}
        />

        {/* Contenu au-dessus */}
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-semibold text-4xl md:text-5xl text-white">
              Dalal ak jàamm
            </h1>
            <p className="mt-5 text-lg leading-relaxed text-white max-w-xl">
              Mame Samba
            </p>

            <div className="mt-10 flex flex-wrap gap-3">
              <Link
                to="/landing"
                className="inline-flex items-center justify-center text-white font-bold px-6 py-4 rounded uppercase text-sm shadow hover:shadow-lg transition ease-linear duration-150"
                style={{ backgroundColor: "#25509d" }}
              >
                Commencer
              </Link>

              <a
                href="#features"
                className="inline-flex items-center justify-center text-gray-800 font-bold px-6 py-4 rounded uppercase text-sm shadow hover:shadow-lg bg-white transition ease-linear duration-150"
              >
                Découvrir les features
              </a>
            </div>
          </div>
        </div>
      </section>

      {/* FEATURES */}
      <section id="features" className="py-24 bg-blueGray-50">
        <div className="container mx-auto px-4">
          <div className="text-center max-w-3xl mx-auto">
            <h2 className="text-3xl md:text-4xl font-semibold text-blueGray-800">
              Ce que vous obtenez
            </h2>
            <p className="text-blueGray-500 mt-4">
              Un starter propre, réactif, et extensible pour présenter votre produit/service.
            </p>
          </div>
          {/* … ajoute ici tes cartes features … */}
        </div>
      </section>

      <Footer />
    </>
  );
}
